package auth

import (
	"errors"
	"os"
	"strings"
	"time"
)

type Config struct {
	Address  string
	Secret   []byte
	Issuer   string
	TokenTTL time.Duration
}

func LoadConfig() (Config, error) {
	c := Config{Address: envOr("AUTH_ADDRESS", ":8080"), Issuer: envOr("AUTH_ISSUER", "auth-service"), TokenTTL: time.Hour}
	secret := os.Getenv("AUTH_SECRET")
	if len([]byte(secret)) < 32 {
		return Config{}, errors.New("AUTH_SECRET must contain at least 32 bytes")
	}
	c.Secret = []byte(secret)
	if raw := os.Getenv("AUTH_TOKEN_TTL"); raw != "" {
		ttl, err := time.ParseDuration(raw)
		if err != nil || ttl <= 0 {
			return Config{}, errors.New("AUTH_TOKEN_TTL must be a positive duration")
		}
		c.TokenTTL = ttl
	}
	if c.Address == "" || strings.TrimSpace(c.Issuer) == "" {
		return Config{}, errors.New("AUTH_ADDRESS and AUTH_ISSUER must not be empty")
	}
	return c, nil
}

func envOr(name, fallback string) string {
	if value := os.Getenv(name); value != "" {
		return value
	}
	return fallback
}
package auth

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"strings"
	"time"
)

var ErrInvalidToken = errors.New("invalid token")

type TokenManager struct {
	secret []byte
	issuer string
	ttl    time.Duration
}

func NewTokenManager(secret []byte, issuer string, ttl time.Duration) *TokenManager {
	return &TokenManager{secret: append([]byte(nil), secret...), issuer: issuer, ttl: ttl}
}

func (m *TokenManager) Create(user Profile, now time.Time) (string, error) {
	id := make([]byte, 16)
	if _, err := rand.Read(id); err != nil {
		return "", err
	}
	header, _ := json.Marshal(map[string]string{"typ": "JWT", "alg": "HS256"})
	claims, err := json.Marshal(map[string]any{"sub": user.ID, "email": user.Email, "iss": m.issuer, "iat": now.Unix(), "exp": now.Add(m.ttl).Unix(), "jti": hex.EncodeToString(id)})
	if err != nil {
		return "", err
	}
	part := base64.RawURLEncoding.EncodeToString(header) + "." + base64.RawURLEncoding.EncodeToString(claims)
	mac := hmac.New(sha256.New, m.secret)
	mac.Write([]byte(part))
	return part + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil)), nil
}

func (m *TokenManager) Validate(token string, now time.Time) (Claims, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
		return Claims{}, ErrInvalidToken
	}
	var header struct {
		Alg string `json:"alg"`
		Typ string `json:"typ"`
	}
	headerBytes, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil || json.Unmarshal(headerBytes, &header) != nil || header.Alg != "HS256" || header.Typ != "JWT" {
		return Claims{}, ErrInvalidToken
	}
	signature, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil {
		return Claims{}, ErrInvalidToken
	}
	mac := hmac.New(sha256.New, m.secret)
	mac.Write([]byte(parts[0] + "." + parts[1]))
	if !hmac.Equal(signature, mac.Sum(nil)) {
		return Claims{}, ErrInvalidToken
	}
	var raw struct {
		Sub, Email, Iss string
		IAT, Exp        int64
		JTI             string
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil || json.Unmarshal(payload, &raw) != nil || raw.Iss != m.issuer || raw.Sub == "" || raw.Email == "" || raw.JTI == "" || raw.IAT <= 0 || raw.Exp <= raw.IAT || now.Unix() >= raw.Exp {
		return Claims{}, ErrInvalidToken
	}
	return Claims{Subject: raw.Sub, Email: raw.Email, Issuer: raw.Iss, IssuedAt: time.Unix(raw.IAT, 0), ExpiresAt: time.Unix(raw.Exp, 0), JWTID: raw.JTI}, nil
}
package auth

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"
	"time"
)

type contextKey string

const claimsContextKey contextKey = "auth.claims"

type Transport struct{ service *Service }
type credentialsRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}
type response struct {
	User        *Profile `json:"user,omitempty"`
	AccessToken string   `json:"access_token,omitempty"`
}
type errorBody struct {
	Error apiError `json:"error"`
}
type apiError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

func NewHandler(service *Service) http.Handler {
	t := &Transport{service: service}
	mux := http.NewServeMux()
	mux.HandleFunc("POST /register", t.register)
	mux.HandleFunc("POST /login", t.login)
	mux.Handle("GET /me", t.requireAuth(http.HandlerFunc(t.me)))
	return t.jsonMiddleware(mux)
}

func (t *Transport) register(w http.ResponseWriter, r *http.Request) {
	var req credentialsRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	profile, err := t.service.Register(req.Email, req.Password)
	if err != nil {
		switch {
		case errors.Is(err, ErrUserExists):
			writeError(w, http.StatusConflict, "user_exists", "email is already registered")
		case errors.Is(err, ErrInvalidEmail):
			writeError(w, http.StatusBadRequest, "invalid_email", "email is invalid")
		default:
			writeError(w, http.StatusBadRequest, "invalid_password", "password must be 8 to 1024 characters")
		}
		return
	}
	writeJSON(w, http.StatusCreated, response{User: &profile})
}

func (t *Transport) login(w http.ResponseWriter, r *http.Request) {
	var req credentialsRequest
	if !decodeJSON(w, r, &req) {
		return
	}
	token, err := t.service.Login(req.Email, req.Password, time.Now())
	if err != nil {
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "email or password is incorrect")
		return
	}
	writeJSON(w, http.StatusOK, response{AccessToken: token})
}

func (t *Transport) me(w http.ResponseWriter, r *http.Request) {
	claims, _ := r.Context().Value(claimsContextKey).(Claims)
	profile := Profile{ID: claims.Subject, Email: claims.Email}
	writeJSON(w, http.StatusOK, response{User: &profile})
}

func (t *Transport) requireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		parts := strings.Fields(r.Header.Get("Authorization"))
		if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
			writeError(w, http.StatusUnauthorized, "unauthorized", "valid Bearer token is required")
			return
		}
		claims, err := t.service.tokens.Validate(parts[1], time.Now())
		if err != nil {
			writeError(w, http.StatusUnauthorized, "unauthorized", "valid Bearer token is required")
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), claimsContextKey, claims)))
	})
}

func (t *Transport) jsonMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		next.ServeHTTP(w, r)
	})
}

func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) bool {
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "request body must be valid JSON")
		return false
	}
	var extra any
	if err := dec.Decode(&extra); err != io.EOF {
		writeError(w, http.StatusBadRequest, "invalid_json", "request body must contain one JSON object")
		return false
	}
	return true
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}
func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, errorBody{Error: apiError{Code: code, Message: message}})
}
package auth

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"strings"
	"time"
)

var ErrInvalidCredentials = errors.New("invalid credentials")
var ErrInvalidEmail = errors.New("invalid email")
var ErrInvalidPassword = errors.New("invalid password")

type Service struct {
	repo   *UserRepository
	tokens *TokenManager
}

func NewService(repo *UserRepository, tokens *TokenManager) *Service {
	return &Service{repo: repo, tokens: tokens}
}

func normalizeEmail(email string) (string, error) {
	email = strings.ToLower(strings.TrimSpace(email))
	if len(email) < 3 || len(email) > 254 || strings.Count(email, "@") != 1 || strings.ContainsAny(email, " \t\r\n") {
		return "", ErrInvalidEmail
	}
	at := strings.IndexByte(email, '@')
	if at < 1 || at == len(email)-1 || !strings.Contains(email[at+1:], ".") || strings.HasPrefix(email[at+1:], ".") || strings.HasSuffix(email, ".") {
		return "", ErrInvalidEmail
	}
	return email, nil
}

func (s *Service) Register(email, password string) (Profile, error) {
	email, err := normalizeEmail(email)
	if err != nil {
		return Profile{}, err
	}
	if len(password) < 8 || len(password) > 1024 {
		return Profile{}, ErrInvalidPassword
	}
	salt, hash, err := hashPassword(password)
	if err != nil {
		return Profile{}, err
	}
	idBytes := make([]byte, 16)
	if _, err = rand.Read(idBytes); err != nil {
		return Profile{}, err
	}
	user := User{ID: hex.EncodeToString(idBytes), Email: email, PasswordSalt: salt, PasswordHash: hash}
	if err = s.repo.Create(user); err != nil {
		return Profile{}, err
	}
	return user.PublicProfile(), nil
}

func (s *Service) Login(email, password string, now time.Time) (string, error) {
	email, err := normalizeEmail(email)
	if err != nil {
		return "", ErrInvalidCredentials
	}
	user, err := s.repo.FindByEmail(email)
	if err != nil || !verifyPassword(password, user.PasswordSalt, user.PasswordHash) {
		return "", ErrInvalidCredentials
	}
	return s.tokens.Create(user.PublicProfile(), now)
}

